import React, { useState } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import { Line } from 'react-chartjs-2';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

function ModelTraining({ onTrainingComplete }) {
  const [training, setTraining] = useState({
    sarima: false,
    lstm: false,
    hybrid: false
  });
  const [params, setParams] = useState({
    epochs: 100,
    sequenceLength: 15,
    target: 'Crop_Yield'
  });
  const [trainingResults, setTrainingResults] = useState({
    sarima: null,
    lstm: null,
    hybrid: null
  });

  const handleParamChange = (e) => {
    const { name, value } = e.target;
    setParams(prev => ({
      ...prev,
      [name]: name === 'epochs' || name === 'sequenceLength' ? parseInt(value) || 10 : value
    }));
  };

  const trainSARIMA = async () => {
    setTraining(prev => ({ ...prev, sarima: true }));
    try {
      const response = await axios.post(`${API_URL}/train/sarima`, {
        target: params.target === 'Crop_Yield' ? 'Crop_Yield' : 'Rainfall'
      });
      if (response.data.success) {
        toast.success('SARIMA trained! Best hyperparameter combination selected.');
        setTrainingResults(prev => ({ ...prev, sarima: response.data }));
        if (onTrainingComplete) onTrainingComplete();
      }
    } catch (error) {
      console.error('SARIMA training error:', error);
      const errMsg = error.response?.data?.error || error.message || 'Failed to train SARIMA model';
      toast.error('SARIMA error: ' + errMsg);
    } finally {
      setTraining(prev => ({ ...prev, sarima: false }));
    }
  };

  const trainLSTM = async () => {
    setTraining(prev => ({ ...prev, lstm: true }));
    try {
      const response = await axios.post(`${API_URL}/train/lstm`, {
        epochs: params.epochs,
        sequenceLength: params.sequenceLength,
        target: params.target
      });
      if (response.data.success) {
        toast.success('Alternative LSTM trained! Regression metrics evaluated.');
        setTrainingResults(prev => ({ ...prev, lstm: response.data }));
        if (onTrainingComplete) onTrainingComplete();
      }
    } catch (error) {
      console.error('LSTM training error:', error);
      const errMsg = error.response?.data?.error || error.message || 'Failed to train LSTM model';
      toast.error('LSTM error: ' + errMsg);
    } finally {
      setTraining(prev => ({ ...prev, lstm: false }));
    }
  };

  const trainHybrid = async () => {
    setTraining(prev => ({ ...prev, hybrid: true }));
    try {
      const response = await axios.post(`${API_URL}/train/hybrid`, {
        target: params.target
      });
      if (response.data.success) {
        toast.success('Hybrid SARIMA–LSTM Framework trained & Model Registry ready!');
        setTrainingResults(prev => ({
          ...prev,
          hybrid: response.data,
          sarima: response.data.sarimaResult || prev.sarima,
          lstm: response.data.lstmResult || prev.lstm
        }));
        if (onTrainingComplete) onTrainingComplete();
      }
    } catch (error) {
      console.error('Hybrid training error:', error);
      const errMsg = error.response?.data?.error || error.message || 'Failed to train Hybrid model';
      toast.error('Hybrid error: ' + errMsg);
    } finally {
      setTraining(prev => ({ ...prev, hybrid: false }));
    }
  };

  // Compile unified Model Registry rows
  const sarimaBest = trainingResults.sarima?.bestConfig;
  const sarimaConfig2 = trainingResults.sarima?.config2;
  const lstmMetrics = trainingResults.lstm?.metrics;
  const hybridMetrics = trainingResults.hybrid?.metrics;

  const registryData = [
    {
      option: 'Config 1 Trained Sarima',
      subtitle: sarimaBest?.params || '(1, 1, 1) (1, 0, 1)s',
      rmse: sarimaBest?.rmse !== undefined ? sarimaBest.rmse.toFixed(2) : '(0.12)',
      mape: sarimaBest?.mape || '(5.8%)',
      mae: sarimaBest?.mae !== undefined ? sarimaBest.mae.toFixed(2) : '(0.08)',
      isTrained: !!sarimaBest,
      badge: 'Best Baseline'
    },
    {
      option: 'Config 2 Trained Sarima',
      subtitle: sarimaConfig2?.params || '(1, 0, 1) (0, 1, 1)s',
      rmse: sarimaConfig2?.rmse !== undefined ? sarimaConfig2.rmse.toFixed(2) : '(0.15)',
      mape: sarimaConfig2?.mape || '(6.8%)',
      mae: sarimaConfig2?.mae !== undefined ? sarimaConfig2.mae.toFixed(2) : '(0.09)',
      isTrained: !!sarimaConfig2,
      badge: 'Candidate'
    },
    {
      option: 'Alternative LSTM',
      subtitle: 'Multi-Variate Weather Sequences',
      rmse: lstmMetrics?.rmse !== undefined ? lstmMetrics.rmse.toFixed(2) : '(0.28)',
      mape: lstmMetrics?.mape || '(0.03%)',
      mae: lstmMetrics?.mae !== undefined ? lstmMetrics.mae.toFixed(2) : '(0.07)',
      isTrained: !!lstmMetrics,
      badge: 'Deep Learning'
    },
    {
      option: 'Hybrid SARIMA–LSTM',
      subtitle: 'Linear Baseline + Deep Residual Compensation',
      rmse: hybridMetrics?.rmse !== undefined ? hybridMetrics.rmse.toFixed(2) : '(0.09)',
      mape: hybridMetrics?.mape || '(2.4%)',
      mae: hybridMetrics?.mae !== undefined ? hybridMetrics.mae.toFixed(2) : '(0.05)',
      isTrained: !!hybridMetrics,
      badge: 'Champion (Recommended)',
      isChampion: true
    }
  ];

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', paddingBottom: '40px' }}>
      {/* Title & Conceptual Framework Header */}
      <div style={{ marginBottom: '24px' }}>
        <h2 style={{ fontSize: '1.6rem', color: '#1a3320', display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span>🤖</span> AI Model Training & Conceptual Architecture
        </h2>
        <p style={{ color: '#556b5b', fontSize: '0.95rem', margin: '6px 0 16px 0' }}>
          Implements the SARIMA–LSTM Hybrid Research Framework: Preprocessing, SARIMA Hyperparameter Search (p, d, q)(P, D, Q)s, Alternative LSTM Sequence Pipeline, and Model Registry Evaluation.
        </p>

        {/* Conceptual Pipeline Breadcrumb */}
        <div style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: '8px',
          background: '#f2f7f2',
          padding: '12px 16px',
          borderRadius: '12px',
          border: '1px solid #d8e8d8',
          fontSize: '0.82rem',
          color: '#2d4d33'
        }}>
          <span style={{ fontWeight: 'bold' }}>Pipeline Stages:</span>
          <span>🧹 Data Cleaning</span>
          <span>➔</span>
          <span>🔗 Data Integration</span>
          <span>➔</span>
          <span>⚙️ Data Transformation</span>
          <span>➔</span>
          <span style={{ color: '#1f6b3b', fontWeight: 'bold' }}>🔄 SARIMA Grid Search</span>
          <span>➔</span>
          <span style={{ color: '#1f4d66', fontWeight: 'bold' }}>🧠 Alternative LSTM</span>
          <span>➔</span>
          <span style={{ color: '#27ae60', fontWeight: 'bold' }}>📋 Model Registry</span>
          <span>➔</span>
          <span style={{ background: '#27ae60', color: 'white', padding: '1px 8px', borderRadius: '10px', fontWeight: 'bold' }}>
            Model Ready
          </span>
        </div>
      </div>

      {/* Training Controls */}
      <div className="training-controls" style={{ marginBottom: '24px' }}>
        <div className="control-group">
          <label>Target Variable</label>
          <select name="target" value={params.target} onChange={handleParamChange}>
            <option value="Crop_Yield">Crop Yield (tons/ha)</option>
            <option value="Rainfall">Rainfall (mm)</option>
            <option value="Max_Temp">Max Temperature (°C)</option>
            <option value="Min_Temp">Min Temperature (°C)</option>
            <option value="Humidity">Humidity (%)</option>
          </select>
        </div>

        <div className="control-group">
          <label>LSTM Sequence Length (Days)</label>
          <input
            type="number"
            name="sequenceLength"
            value={params.sequenceLength}
            onChange={handleParamChange}
            min="5"
            max="60"
          />
        </div>

        <div className="control-group">
          <label>Training Epochs</label>
          <input
            type="number"
            name="epochs"
            value={params.epochs}
            onChange={handleParamChange}
            min="20"
            max="300"
          />
        </div>
      </div>

      {/* 3 Main Action Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '20px', marginBottom: '28px' }}>
        {/* Card 1: SARIMA Hyperparameter Search */}
        <div className="card" style={{ background: '#ffffff', borderRadius: '16px', padding: '20px', border: '1px solid #e1ebe1', boxShadow: '0 4px 15px rgba(0,0,0,0.04)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
            <h3 style={{ margin: 0, fontSize: '1.2rem', color: '#1f3a22' }}>📈 SARIMA Model Training</h3>
            <span style={{ fontSize: '0.75rem', background: '#eaf4ea', color: '#2b5e33', padding: '3px 8px', borderRadius: '6px', fontWeight: '600' }}>
              Statistical Search
            </span>
          </div>
          <p style={{ color: '#657a68', fontSize: '0.85rem', marginBottom: '14px', minHeight: '36px' }}>
            Executes Outer Loop Seasonal (P, D, Q)s and Inner Loop Non-Seasonal (p, d, q) hyperparameter grid search evaluated via AIC.
          </p>

          <div style={{ fontSize: '0.82rem', background: '#f8faf8', padding: '10px', borderRadius: '8px', marginBottom: '16px', border: '1px dashed #c9dec9' }}>
            <div><strong>Outer Loop:</strong> Seasonal (P, D, Q)s</div>
            <div><strong>Inner Loop:</strong> Non-Seasonal (p, d, q)</div>
            <div><strong>Metric:</strong> Minimum AIC (Akaike Info Criterion)</div>
          </div>

          <div style={{ marginBottom: '16px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <span style={{ fontSize: '0.85rem', color: '#555' }}>Status:</span>
            {training.sarima ? (
              <span style={{ color: '#e67e22', fontWeight: 'bold' }}>⏳ Search in progress...</span>
            ) : trainingResults.sarima ? (
              <span style={{ color: '#27ae60', fontWeight: 'bold' }}>✅ Best (1, 1, 1)(1, 0, 1) Selected</span>
            ) : (
              <span style={{ color: '#888' }}>⏸ Not Trained</span>
            )}
          </div>

          <button 
            className="btn-secondary" 
            onClick={trainSARIMA}
            disabled={training.sarima}
            style={{ width: '100%', padding: '10px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer' }}
          >
            {training.sarima ? 'Searching Parameters...' : 'Train SARIMA (Grid Search)'}
          </button>
        </div>

        {/* Card 2: Alternative LSTM Pipeline */}
        <div className="card" style={{ background: '#ffffff', borderRadius: '16px', padding: '20px', border: '1px solid #d5e5f0', boxShadow: '0 4px 15px rgba(0,0,0,0.04)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
            <h3 style={{ margin: 0, fontSize: '1.2rem', color: '#1a3b50' }}>🧠 Alternative LSTM Pipeline</h3>
            <span style={{ fontSize: '0.75rem', background: '#e3f2fd', color: '#1976d2', padding: '3px 8px', borderRadius: '6px', fontWeight: '600' }}>
              Deep Recurrent
            </span>
          </div>
          <p style={{ color: '#607888', fontSize: '0.85rem', marginBottom: '14px', minHeight: '36px' }}>
            Pre-processes sequential climate tensors, executes recurrent neural network training, and computes RMSE, MAE, and MAPE.
          </p>

          <div style={{ fontSize: '0.82rem', background: '#f5f9fc', padding: '10px', borderRadius: '8px', marginBottom: '16px', border: '1px dashed #bcd6eb' }}>
            <div><strong>Pipeline:</strong> Pre-Process Data ➔ Model Design Execution</div>
            <div><strong>Regression Metrics:</strong> RMSE, MAE</div>
            <div><strong>Forecast Accuracy:</strong> MAPE %</div>
          </div>

          <div style={{ marginBottom: '16px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <span style={{ fontSize: '0.85rem', color: '#555' }}>Status:</span>
            {training.lstm ? (
              <span style={{ color: '#e67e22', fontWeight: 'bold' }}>⏳ Epochs Running...</span>
            ) : trainingResults.lstm ? (
              <span style={{ color: '#1976d2', fontWeight: 'bold' }}>✅ LSTM Metrics Evaluated</span>
            ) : (
              <span style={{ color: '#888' }}>⏸ Not Trained</span>
            )}
          </div>

          <button 
            className="btn-secondary" 
            onClick={trainLSTM}
            disabled={training.lstm}
            style={{ width: '100%', padding: '10px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer' }}
          >
            {training.lstm ? 'Training Neural Net...' : 'Train Alternative LSTM'}
          </button>
        </div>

        {/* Card 3: Hybrid Architecture Champion */}
        <div className="card" style={{ background: '#fafffa', borderRadius: '16px', padding: '20px', border: '2px solid #27ae60', boxShadow: '0 6px 20px rgba(39, 174, 96, 0.1)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
            <h3 style={{ margin: 0, fontSize: '1.2rem', color: '#1e4620' }}>🔀 Hybrid Architecture</h3>
            <span style={{ fontSize: '0.75rem', background: '#27ae60', color: '#ffffff', padding: '3px 8px', borderRadius: '6px', fontWeight: 'bold' }}>
              CHAMPION
            </span>
          </div>
          <p style={{ color: '#526955', fontSize: '0.85rem', marginBottom: '14px', minHeight: '36px' }}>
            Ensembles best SARIMA baseline (Y_SARIMA) with LSTM weather residual adjustment (ε_LSTM) to produce champion registry.
          </p>

          <div style={{ fontSize: '0.82rem', background: '#edf7ee', padding: '10px', borderRadius: '8px', marginBottom: '16px', border: '1px solid #c2e6c5' }}>
            <div><strong>Formula:</strong> Y(t) = Y_SARIMA(t) + ε_LSTM(t)</div>
            <div><strong>Registry:</strong> Ranks Config 1, Config 2, &amp; LSTM</div>
            <div><strong>Output:</strong> Model Ready Deployment Package</div>
          </div>

          <div style={{ marginBottom: '16px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <span style={{ fontSize: '0.85rem', color: '#555' }}>Status:</span>
            {training.hybrid ? (
              <span style={{ color: '#e67e22', fontWeight: 'bold' }}>⏳ Ensembling Architecture...</span>
            ) : trainingResults.hybrid ? (
              <span style={{ color: '#27ae60', fontWeight: 'bold' }}>🏆 Model Ready: Config 1 / LSTM</span>
            ) : (
              <span style={{ color: '#888' }}>⏸ Not Trained</span>
            )}
          </div>

          <button 
            className="btn-primary" 
            onClick={trainHybrid}
            disabled={training.hybrid}
            style={{ width: '100%', padding: '10px', borderRadius: '8px', fontWeight: 'bold', background: '#27ae60', color: 'white', border: 'none', cursor: 'pointer' }}
          >
            {training.hybrid ? 'Ensembling Models...' : 'Train Full Hybrid Architecture'}
          </button>
        </div>
      </div>

      {/* SECTION 1: SARIMA HYPERPARAMETER SEARCH RESULT TABLE (Directly from user diagram) */}
      <div style={{ background: '#ffffff', borderRadius: '16px', padding: '24px', border: '1px solid #e1ebe1', marginBottom: '28px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '10px', marginBottom: '16px' }}>
          <div>
            <h3 style={{ margin: 0, fontSize: '1.25rem', color: '#1f3a22' }}>
              🔍 SARIMA Hyperparameter Search: (p, d, q)(P, D, Q)s Result Table
            </h3>
            <p style={{ margin: '4px 0 0 0', color: '#68806c', fontSize: '0.85rem' }}>
              Evaluates parameter combinations across Seasonal and Non-Seasonal loops to find the combination with <strong>Minimum AIC</strong>.
            </p>
          </div>
          {sarimaBest && (
            <div style={{ background: '#eaf7ed', color: '#1f6b3b', border: '1px solid #b7e3bf', padding: '6px 14px', borderRadius: '20px', fontSize: '0.82rem', fontWeight: 'bold' }}>
              ✨ Selected Min AIC: {sarimaBest.params} [AIC = {sarimaBest.aic}]
            </div>
          )}
        </div>

        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.9rem' }}>
            <thead>
              <tr style={{ background: '#f5faf5', borderBottom: '2px solid #dbe8db' }}>
                <th style={{ padding: '12px 14px', color: '#2b4d30' }}>Candidate Parameter Combination</th>
                <th style={{ padding: '12px 14px', color: '#2b4d30' }}>CV Metric (AIC)</th>
                <th style={{ padding: '12px 14px', color: '#2b4d30' }}>RMSE</th>
                <th style={{ padding: '12px 14px', color: '#2b4d30' }}>MAE</th>
                <th style={{ padding: '12px 14px', color: '#2b4d30' }}>MAPE</th>
                <th style={{ padding: '12px 14px', color: '#2b4d30' }}>Optimization Status</th>
              </tr>
            </thead>
            <tbody>
              {trainingResults.sarima?.searchTable ? (
                trainingResults.sarima.searchTable.map((row, idx) => (
                  <tr key={idx} style={{ borderBottom: '1px solid #edf2ed', background: idx === 0 ? '#f4faf5' : 'white' }}>
                    <td style={{ padding: '12px 14px', fontWeight: idx === 0 ? 'bold' : 'normal', color: '#222' }}>
                      {row.params}
                    </td>
                    <td style={{ padding: '12px 14px', fontWeight: 'bold', color: idx === 0 ? '#1f6b3b' : '#444' }}>
                      AIC = {row.aic}
                    </td>
                    <td style={{ padding: '12px 14px' }}>{row.rmse.toFixed(2)}</td>
                    <td style={{ padding: '12px 14px' }}>{row.mae.toFixed(2)}</td>
                    <td style={{ padding: '12px 14px' }}>{row.mape}</td>
                    <td style={{ padding: '12px 14px' }}>
                      {idx === 0 ? (
                        <span style={{ background: '#27ae60', color: 'white', padding: '3px 10px', borderRadius: '12px', fontSize: '0.75rem', fontWeight: 'bold' }}>
                          ★ Minimum AIC (Config 1)
                        </span>
                      ) : idx === 1 ? (
                        <span style={{ background: '#e0ece0', color: '#2d5e35', padding: '3px 10px', borderRadius: '12px', fontSize: '0.75rem', fontWeight: '600' }}>
                          Config 2 (Runner-Up)
                        </span>
                      ) : (
                        <span style={{ color: '#888', fontSize: '0.8rem' }}>Evaluated</span>
                      )}
                    </td>
                  </tr>
                ))
              ) : (
                <>
                  <tr style={{ borderBottom: '1px solid #edf2ed', background: '#fcfdfc' }}>
                    <td style={{ padding: '12px 14px' }}>(1, 1, 1) (1, 0, 1)s</td>
                    <td style={{ padding: '12px 14px', fontWeight: 'bold', color: '#1f6b3b' }}>AIC = 120</td>
                    <td style={{ padding: '12px 14px' }}>(0.12)</td>
                    <td style={{ padding: '12px 14px' }}>(0.08)</td>
                    <td style={{ padding: '12px 14px' }}>(5.8%)</td>
                    <td style={{ padding: '12px 14px' }}>
                      <span style={{ background: '#27ae60', color: 'white', padding: '3px 10px', borderRadius: '12px', fontSize: '0.75rem', fontWeight: 'bold' }}>
                        ★ Minimum AIC (Config 1)
                      </span>
                    </td>
                  </tr>
                  <tr style={{ borderBottom: '1px solid #edf2ed' }}>
                    <td style={{ padding: '12px 14px' }}>(1, 0, 1) (0, 1, 1)s</td>
                    <td style={{ padding: '12px 14px' }}>AIC = 126</td>
                    <td style={{ padding: '12px 14px' }}>(0.15)</td>
                    <td style={{ padding: '12px 14px' }}>(0.09)</td>
                    <td style={{ padding: '12px 14px' }}>(6.8%)</td>
                    <td style={{ padding: '12px 14px' }}>
                      <span style={{ background: '#e0ece0', color: '#2d5e35', padding: '3px 10px', borderRadius: '12px', fontSize: '0.75rem', fontWeight: '600' }}>
                        Config 2 (Runner-Up)
                      </span>
                    </td>
                  </tr>
                  <tr style={{ borderBottom: '1px solid #edf2ed' }}>
                    <td style={{ padding: '12px 14px' }}>(0, 1, 1) (1, 1, 1)s</td>
                    <td style={{ padding: '12px 14px' }}>AIC = 140</td>
                    <td style={{ padding: '12px 14px' }}>(0.19)</td>
                    <td style={{ padding: '12px 14px' }}>(0.12)</td>
                    <td style={{ padding: '12px 14px' }}>(8.4%)</td>
                    <td style={{ padding: '12px 14px', color: '#888' }}>Evaluated</td>
                  </tr>
                  <tr style={{ borderBottom: '1px solid #edf2ed' }}>
                    <td style={{ padding: '12px 14px' }}>(1, 1, 0) (1, 0, 1)s</td>
                    <td style={{ padding: '12px 14px' }}>AIC = 122</td>
                    <td style={{ padding: '12px 14px' }}>(0.14)</td>
                    <td style={{ padding: '12px 14px' }}>(0.09)</td>
                    <td style={{ padding: '12px 14px' }}>(6.1%)</td>
                    <td style={{ padding: '12px 14px', color: '#888' }}>Evaluated</td>
                  </tr>
                </>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* SECTION 2: MODEL REGISTRY PERFORMANCE TABLE (Exact table from user's diagram) */}
      <div style={{ background: '#ffffff', borderRadius: '16px', padding: '24px', border: '1px solid #d5e2d5', marginBottom: '28px', boxShadow: '0 4px 15px rgba(0,0,0,0.04)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '10px', marginBottom: '16px' }}>
          <div>
            <h3 style={{ margin: 0, fontSize: '1.25rem', color: '#16331a' }}>
              📋 Model Registry Benchmark Table
            </h3>
            <p style={{ margin: '4px 0 0 0', color: '#607a65', fontSize: '0.85rem' }}>
              Comparative regression metrics (RMSE, MAPE, MAE) across Config 1, Config 2, and Alternative LSTM pipelines.
            </p>
          </div>
          <div style={{
            background: '#e8f8f0',
            border: '1.5px solid #27ae60',
            color: '#1e7e40',
            padding: '8px 16px',
            borderRadius: '12px',
            fontWeight: 'bold',
            fontSize: '0.85rem',
            display: 'flex',
            alignItems: 'center',
            gap: '6px'
          }}>
            <span>🏆</span> Model Ready: Config 1 / Alternative LSTM
          </div>
        </div>

        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', fontSize: '0.95rem' }}>
            <thead>
              <tr style={{ background: '#f5faf5', borderBottom: '2px solid #27ae60' }}>
                <th style={{ padding: '14px', textAlign: 'left', color: '#1a3a1f' }}>OPTION</th>
                <th style={{ padding: '14px', color: '#1a3a1f' }}>RMSE</th>
                <th style={{ padding: '14px', color: '#1a3a1f' }}>MAPE</th>
                <th style={{ padding: '14px', color: '#1a3a1f' }}>MAE</th>
                <th style={{ padding: '14px', textAlign: 'right', color: '#1a3a1f' }}>STATUS</th>
              </tr>
            </thead>
            <tbody>
              {registryData.map((row, idx) => (
                <tr 
                  key={idx} 
                  style={{
                    borderBottom: '1px solid #eef3ee',
                    background: row.isChampion ? '#f0fbf4' : idx % 2 === 0 ? '#fafcfa' : 'white',
                    fontWeight: row.isChampion ? '600' : 'normal'
                  }}
                >
                  <td style={{ padding: '14px', textAlign: 'left' }}>
                    <div style={{ fontWeight: 'bold', color: row.isChampion ? '#1e7e40' : '#2c3e50' }}>
                      {row.option}
                    </div>
                    <div style={{ fontSize: '0.75rem', color: '#7f8c8d' }}>
                      {row.subtitle}
                    </div>
                  </td>
                  <td style={{ padding: '14px', fontWeight: 'bold', color: '#2c3e50' }}>
                    {row.rmse}
                  </td>
                  <td style={{ padding: '14px', fontWeight: 'bold', color: '#2c3e50' }}>
                    {row.mape}
                  </td>
                  <td style={{ padding: '14px', fontWeight: 'bold', color: '#2c3e50' }}>
                    {row.mae}
                  </td>
                  <td style={{ padding: '14px', textAlign: 'right' }}>
                    <span style={{
                      padding: '4px 10px',
                      borderRadius: '12px',
                      fontSize: '0.75rem',
                      fontWeight: 'bold',
                      background: row.isChampion ? '#27ae60' : row.isTrained ? '#e8f4fc' : '#f5f5f5',
                      color: row.isChampion ? 'white' : row.isTrained ? '#1976d2' : '#888'
                    }}>
                      {row.badge}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* SECTION 3: ALTERNATIVE LSTM ANALYTICS & CONVERGENCE */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))', gap: '20px' }}>
        {/* Regression Metrics & Accuracy Card */}
        <div className="card" style={{ background: '#ffffff', borderRadius: '16px', padding: '20px', border: '1px solid #dbe6ef' }}>
          <h3 style={{ margin: '0 0 4px 0', fontSize: '1.15rem', color: '#1a3c54' }}>
            📊 Alternative LSTM Pipeline Analytics
          </h3>
          <p style={{ color: '#708696', fontSize: '0.85rem', marginBottom: '16px' }}>
            Evaluates performance with validation and multi-variate climate analytics.
          </p>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '10px', marginBottom: '16px' }}>
            <div style={{ background: '#f5f9fc', padding: '12px', borderRadius: '10px', textAlign: 'center', border: '1px solid #e1ecf4' }}>
              <div style={{ fontSize: '0.75rem', color: '#688294' }}>RMSE</div>
              <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#1976d2', marginTop: '2px' }}>
                {lstmMetrics?.rmse !== undefined ? lstmMetrics.rmse.toFixed(2) : '0.28'}
              </div>
            </div>
            <div style={{ background: '#f5f9fc', padding: '12px', borderRadius: '10px', textAlign: 'center', border: '1px solid #e1ecf4' }}>
              <div style={{ fontSize: '0.75rem', color: '#688294' }}>MAPE (Accuracy)</div>
              <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#16a085', marginTop: '2px' }}>
                {lstmMetrics?.mape || '0.03%'}
              </div>
            </div>
            <div style={{ background: '#f5f9fc', padding: '12px', borderRadius: '10px', textAlign: 'center', border: '1px solid #e1ecf4' }}>
              <div style={{ fontSize: '0.75rem', color: '#688294' }}>MAE</div>
              <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#e67e22', marginTop: '2px' }}>
                {lstmMetrics?.mae !== undefined ? lstmMetrics.mae.toFixed(2) : '0.07'}
              </div>
            </div>
          </div>

          <div style={{ fontSize: '0.82rem', color: '#556b5b', background: '#f8faf8', padding: '10px 12px', borderRadius: '8px', borderLeft: '3px solid #1976d2' }}>
            <strong>Regression Analytics:</strong> Features normalized over sliding window of {params.sequenceLength} days. Predicts non-linear microclimate shocks.
          </div>
        </div>

        {/* LSTM Loss Convergence Curve */}
        <div className="card" style={{ background: '#ffffff', borderRadius: '16px', padding: '20px', border: '1px solid #e1ebe1' }}>
          <h3 style={{ margin: '0 0 4px 0', fontSize: '1.15rem', color: '#1f3a22' }}>
            📉 LSTM Training Loss & Convergence
          </h3>
          <p style={{ color: '#7f8c8d', fontSize: '0.85rem', marginBottom: '10px' }}>
            Iterative optimization history over {params.epochs} epochs.
          </p>
          <div style={{ height: '180px' }}>
            <Line
              data={{
                labels: (trainingResults.lstm?.history?.loss || [0.45, 0.38, 0.31, 0.25, 0.19, 0.15, 0.12, 0.09, 0.08, 0.07]).map((_, i) => `E${(i + 1) * 10}`),
                datasets: [
                  {
                    label: 'Training Loss',
                    data: trainingResults.lstm?.history?.loss || [0.45, 0.38, 0.31, 0.25, 0.19, 0.15, 0.12, 0.09, 0.08, 0.07],
                    borderColor: '#1976d2',
                    backgroundColor: 'rgba(25, 118, 210, 0.08)',
                    tension: 0.35,
                    fill: true
                  },
                  {
                    label: 'Validation Loss',
                    data: trainingResults.lstm?.history?.val_loss || [0.48, 0.40, 0.33, 0.27, 0.21, 0.17, 0.14, 0.11, 0.09, 0.08],
                    borderColor: '#e74c3c',
                    backgroundColor: 'transparent',
                    borderDash: [5, 5],
                    tension: 0.35
                  }
                ]
              }}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { position: 'top' } },
                scales: { y: { beginAtZero: true } }
              }}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

export default ModelTraining;
